import { marked } from "../../../vendor/marked/marked.esm.js";

// The comment rules' Reviews section defines this review. The wait prints its
// template; merge accepts only a completed review of the current head.
export const reviewsSection = ".repo-standards/rules/comments.md#reviews";

export const reviewTemplate = (head) => [
  "> _This was generated by AI._",
  "",
  `Head: ${head}`,
  "Standards: <the Standards review's actual outcome>",
  "Spec: <the Spec review's actual outcome>",
  "Fixed: <Nothing, or what this round fixed>",
  "Findings: <None, or one list item per finding below>",
  "- `<path>:<line>` <the finding>",
];

const fields = ["Head", "Standards", "Spec", "Fixed", "Findings"];
const field = new RegExp(`^(${fields.join("|")}):[\\t ]*(.*?)[\\t ]*$`);
const item = /^[-*][\t ]+/;
// A finding starts with its file and line, optionally in a code span.
const located = /^[-*][\t ]+(`?)[^\s`<>]+:\d+(?:-\d+)?\1[\t ]+\S/;

const placeholders = reviewTemplate("").filter((line) => line.includes("<"));
const completed = (value) =>
  Boolean(value?.trim()) &&
  !/^(?:TODO|TBD|placeholder|_?No response_?|<[^>]*>|\[[^\]]*\]|\{[^}]*\})[.!]?$/i.test(
    value,
  ) &&
  !placeholders.some((line) => value.includes(line.slice(line.indexOf("<"))));

const blank = (text) => text.replace(/[^\r\n]/g, " ");

// The lines a reader sees outside examples, built from the visible tokens
// rather than by masking source positions, which tokenization does not always
// preserve. Any other token, such as code, a quote or a link definition,
// becomes one blank line, so its content can neither supply evidence nor join
// the lines around it. Text keeps its lines inside list items too, so a field
// continuing an item still counts. An item's first line keeps its marker unless
// an example opens it, indented when nested, so only top-level items are
// findings.
function visibleLines(tokens, nested = false) {
  return tokens.flatMap((token) => {
    if (["paragraph", "text", "heading", "html"].includes(token.type))
      return token.raw.replace(/\n+$/, "").split("\n");
    if (token.type !== "list") return [""];
    return token.items.flatMap((entry) => {
      const [first, ...rest] = visibleLines(entry.tokens, true);
      const marker = /^[\t ]*\S+[\t ]*/.exec(entry.raw)?.[0] ?? "";
      const opening = (nested ? "  " : "") + marker + first;
      return [first?.trim() ? opening : "", ...rest];
    });
  });
}

// A review's fields in the template's shape, or null when it is not one: the
// head it names, whether it is complete, and whether it holds (complete, with
// no open finding).
function readReview(body) {
  if (typeof body !== "string") return null;
  // Blank comments in place, so hiding content never joins fragments into a
  // field or a head SHA.
  const lines = visibleLines(marked.lexer(body))
    .join("\n")
    .replace(/<!--[\s\S]*?(?:-->|$)/g, blank)
    .split("\n");
  const entries = lines.flatMap((line, index) => {
    const match = field.exec(line);
    return match ? [{ key: match[1], value: match[2], index }] : [];
  });
  if (
    entries.length !== fields.length ||
    new Set(entries.map(({ key }) => key)).size !== fields.length
  )
    return null;
  const byField = Object.fromEntries(entries.map((entry) => [entry.key, entry]));
  const next = entries.find(({ index }) => index > byField.Findings.index);
  const findings = lines
    .slice(byField.Findings.index + 1, next?.index)
    .filter((line) => item.test(line));
  const none = /^None\.?$/i.test(byField.Findings.value);
  const findingsComplete = byField.Findings.value
    ? none && findings.length === 0
    : findings.length > 0 && findings.every((line) => located.test(line));
  const complete =
    ["Standards", "Spec", "Fixed"].every((key) =>
      completed(byField[key].value),
    ) && findingsComplete;
  return { head: byField.Head.value, complete, holds: complete && none };
}

// The full head SHA a review in the template names, if any.
export function reviewedHead(body) {
  const head = readReview(body)?.head;
  return /^[0-9a-f]{40}$/.test(head ?? "") ? head : null;
}

export function completeReview(body, head) {
  const review = readReview(body);
  return review !== null && review.head === head && review.complete;
}

// A review holds when it is complete and leaves no open finding.
export function holdingReview(body, head) {
  const review = readReview(body);
  return review !== null && review.head === head && review.holds;
}
